Future<void> seedFirestore() async {
  final db = FirebaseFirestore.instance;
  const maxWrites = 400;
  WriteBatch batch = db.batch();
  int writes = 0;

  Future<void> flushIfNeeded() async {
    if (writes >= maxWrites) {
      await batch.commit();
      batch = db.batch();
      writes = 0;
    }
  }

  for (final x in seedSchools) {
    final ref = db.collection('schools').doc(x['schoolId'] as String);
    batch.set(ref, {
      'name': x['name'], 'address': x['address'], 'districtId': x['districtId'],
      'createdAt': _timestamp(x['createdAt']), 'updatedAt': _timestamp(x['updatedAt']),
    });
    writes++; await flushIfNeeded();
  }

  for (final x in seedAttendance) {
    final ref = db.collection('schools').doc(x['schoolId'] as String)
        .collection('attendance').doc(x['documentId'] as String);
    batch.set(ref, {
      'attendancePercentage': x['attendancePercentage'], 'date': x['date'],
      'status': x['status'], 'submittedBy': x['submittedBy'],
      'createdAt': _timestamp(x['createdAt']), 'updatedAt': _timestamp(x['updatedAt']),
    });
    writes++; await flushIfNeeded();
  }

  for (final x in seedFeePeriods) {
    final ref = db.collection('schools').doc(x['schoolId'] as String)
        .collection('feePeriods').doc(x['periodId'] as String);
    batch.set(ref, {
      'totalDue': x['totalDue'], 'totalSubmitted': x['totalSubmitted'],
      'status': x['status'], 'updatedBy': x['updatedBy'],
      'createdAt': _timestamp(x['createdAt']), 'updatedAt': _timestamp(x['updatedAt']),
    });
    writes++; await flushIfNeeded();
  }

  for (final x in seedExams) {
    final ref = db.collection('schools').doc(x['schoolId'] as String)
        .collection('exams').doc(x['examId'] as String);
    batch.set(ref, {
      'examName': x['examName'], 'subject': x['subject'],
      'classNumber': x['classNumber'],
      'scheduledDate': _timestamp(x['scheduledDate']),
      'status': x['status'],
      'completedAt': x['completedAt'] == null ? null : _timestamp(x['completedAt']),
      'createdAt': _timestamp(x['createdAt']), 'updatedAt': _timestamp(x['updatedAt']),
    });
    writes++; await flushIfNeeded();
  }

  for (final x in seedFeedback) {
    final ref = db.collection('schools').doc(x['schoolId'] as String)
        .collection('feedback').doc(x['feedbackId'] as String);
    batch.set(ref, {
      'text': x['text'], 'symbol': x['symbol'], 'createdBy': x['createdBy'],
      'createdAt': _timestamp(x['createdAt']),
    });
    writes++; await flushIfNeeded();
  }

  if (writes > 0) await batch.commit();
}

Timestamp _timestamp(String iso) =>
    Timestamp.fromDate(DateTime.parse(iso).toUtc());
